import{_ as o,o as e,c as d,a6 as r}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"方法","description":"安全性、幂等性、可缓存性——九个方法的精确语义与请求体约束。","frontmatter":{"title":"方法","description":"安全性、幂等性、可缓存性——九个方法的精确语义与请求体约束。","source":"https://daiw.org/manual/http11/methods"},"headers":[],"relativePath":"manual/computer-programming/http11/methods.md","filePath":"manual/computer-programming/http11/methods.md"}'),a={name:"manual/computer-programming/http11/methods.md"};function c(n,t,l,s,i,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h1><h2 id="语法与匹配规则" tabindex="-1">语法与匹配规则 <a class="header-anchor" href="#语法与匹配规则" aria-label="Permalink to &quot;语法与匹配规则&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>method = token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>大小写敏感</strong>，全大写是注册惯例而非语法要求。服务端匹配方法时<strong>必须</strong>做精确字节比较：收到 <code>Get</code> 时不得当作 <code>GET</code>。</p><p>两个易混的拒绝码：</p><table tabindex="0"><thead><tr><th>情况</th><th>状态码</th><th>附加要求</th></tr></thead><tbody><tr><td>服务端<strong>根本不实现</strong>该方法</td><td><strong>501 Not Implemented</strong></td><td>—</td></tr><tr><td>方法已实现，但<strong>目标资源</strong>不支持</td><td><strong>405 Method Not Allowed</strong></td><td><strong>MUST</strong> 带 <code>Allow</code> 字段列出该资源支持的方法</td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Allow = #method</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>Allow: GET, HEAD, PUT</code>。空值合法，表示该资源不允许任何方法。</p><h2 id="三个属性" tabindex="-1">三个属性 <a class="header-anchor" href="#三个属性" aria-label="Permalink to &quot;三个属性&quot;">​</a></h2><p>每个方法有三个正交属性，决定中间件能对它做什么：</p><ul><li><strong>安全（safe）</strong>——语义上只读。客户端发起时不期望产生副作用。服务端实际做了什么（如写日志、计数）不影响该分类，因为<strong>责任不在客户端</strong>。</li><li><strong>幂等（idempotent）</strong>——同一请求执行 N 次（N ≥ 1）与执行一次对服务器的<strong>预期效果</strong>相同。响应本身可以不同（如 <code>DELETE</code> 第二次返回 404）。所有安全方法都幂等。</li><li><strong>可缓存（cacheable）</strong>——响应允许被存储并复用。还需状态码本身可缓存且无 <code>no-store</code> 等指令。</li></ul><table tabindex="0"><thead><tr><th>方法</th><th>安全</th><th>幂等</th><th>可缓存</th><th>请求体</th><th>响应体</th></tr></thead><tbody><tr><td><code>GET</code></td><td>✅</td><td>✅</td><td>✅</td><td>不应有</td><td>有</td></tr><tr><td><code>HEAD</code></td><td>✅</td><td>✅</td><td>✅</td><td>不应有</td><td><strong>恒无</strong></td></tr><tr><td><code>POST</code></td><td>❌</td><td>❌</td><td>⚠️ 仅显式</td><td>有</td><td>有</td></tr><tr><td><code>PUT</code></td><td>❌</td><td>✅</td><td>❌</td><td>有</td><td>可有</td></tr><tr><td><code>DELETE</code></td><td>❌</td><td>✅</td><td>❌</td><td>不应有</td><td>可有</td></tr><tr><td><code>CONNECT</code></td><td>❌</td><td>❌</td><td>❌</td><td>无</td><td>无（转隧道）</td></tr><tr><td><code>OPTIONS</code></td><td>✅</td><td>✅</td><td>❌</td><td>不应有</td><td>可有</td></tr><tr><td><code>TRACE</code></td><td>✅</td><td>✅</td><td>❌</td><td><strong>MUST NOT</strong></td><td>有（回显）</td></tr><tr><td><code>PATCH</code></td><td>❌</td><td>❌</td><td>⚠️ 仅显式</td><td>有</td><td>可有</td></tr></tbody></table><p><strong>幂等的工程意义</strong>：连接在收到响应前中断时，客户端<strong>仅可自动重试幂等方法</strong>。<code>POST</code>/<code>PATCH</code> 的重试必须由上层决策（幂等键、去重表），否则重复下单。</p><h2 id="get" tabindex="-1">GET <a class="header-anchor" href="#get" aria-label="Permalink to &quot;GET&quot;">​</a></h2><p>检索目标资源的当前表示。</p><ul><li>支持<a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件请求</a>与<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围请求</a>——<code>GET</code> 是唯一被要求支持 <code>Range</code> 的方法。</li><li>客户端 <strong>SHOULD NOT</strong> 在 <code>GET</code> 中发送请求体：语义未定义，且部分实现直接拒绝（或在代理链上被丢弃，引发走私分歧）。需要复杂查询条件时用 <code>POST</code> 或把条件放进 query。</li><li>成功：<code>200</code>。资源无内容时也应是 <code>200</code> + 空体或 <code>204</code>。</li></ul><h2 id="head" tabindex="-1">HEAD <a class="header-anchor" href="#head" aria-label="Permalink to &quot;HEAD&quot;">​</a></h2><p>与 <code>GET</code> 完全相同，但<strong>响应恒无消息体</strong>。</p><ul><li>服务端 <strong>SHOULD</strong> 返回与对应 <code>GET</code> <strong>相同的头字段</strong>（含 <code>Content-Length</code>、<code>ETag</code>、<code>Content-Type</code>）。此处的 <code>Content-Length</code> 指「若为 GET 会返回多长」，接收方<strong>不得</strong>据此读体。</li><li>用途：检查存在性、验证缓存、读取元数据而不传输体。</li><li>缓存中 <code>HEAD</code> 响应可用于更新已存储的 <code>GET</code> 响应的头；若 <code>Content-Length</code>/<code>ETag</code> 与已存储副本不符，<strong>必须</strong>作废该缓存条目。</li></ul><h2 id="post" tabindex="-1">POST <a class="header-anchor" href="#post" aria-label="Permalink to &quot;POST&quot;">​</a></h2><p>按资源自身语义处理所载荷。它是唯一「语义由目标资源定义」的方法——协议不规定它做什么。</p><ul><li>不幂等：重复提交产生重复效果。</li><li><strong>可缓存性特殊</strong>：<code>POST</code> 响应仅在带<strong>显式新鲜度信息</strong>（<code>Cache-Control: max-age=...</code> 或 <code>Expires</code>）时才可缓存，且后续只能被同 URI 的 <code>GET</code>/<code>HEAD</code> 命中。绝大多数实现直接不缓存。</li><li>常见响应： <ul><li><code>201 Created</code> + <code>Location</code> 指向新建资源。</li><li><code>200</code>/<code>204</code> 表示已处理但未新建。</li><li><code>303 See Other</code> + <code>Location</code>——POST/Redirect/GET 模式，避免刷新重复提交。</li></ul></li></ul><h2 id="put" tabindex="-1">PUT <a class="header-anchor" href="#put" aria-label="Permalink to &quot;PUT&quot;">​</a></h2><p>用请求体<strong>完整替换</strong>目标资源的表示。</p><ul><li>幂等：连发 N 次等价于一次。这是与 <code>POST</code> 的核心区别，不是「新建 vs 更新」。</li><li><strong>必须整体替换</strong>，不做部分更新——部分更新用 <code>PATCH</code>。</li><li><code>Content-Range</code> 在 <code>PUT</code> 中<strong>无意义</strong>，服务端收到带 <code>Content-Range</code> 的 <code>PUT</code> <strong>MUST</strong> 返回 <code>400</code>。</li><li>响应：新建返回 <code>201</code>（带 <code>Location</code>），覆盖已有返回 <code>200</code>/<code>204</code>。</li><li>服务端 <strong>MAY</strong> 忽略或改写客户端发来的验证器相关字段；若存储的表示与请求体不同（如做了规范化），响应 <strong>MUST NOT</strong> 暗示两者一致——应返回 <code>200</code> 并说明，或不带 <code>ETag</code>。</li></ul><h2 id="delete" tabindex="-1">DELETE <a class="header-anchor" href="#delete" aria-label="Permalink to &quot;DELETE&quot;">​</a></h2><p>请求删除目标资源与其 URI 的映射。</p><ul><li>幂等但<strong>不安全</strong>。第二次 <code>DELETE</code> 通常返回 <code>404</code>/<code>410</code>——响应不同不影响幂等性判定。</li><li>响应：<code>204</code>（已删、无内容）、<code>200</code>（已删、返回状态描述）、<code>202</code>（已受理、异步删除）。</li><li>请求体语义未定义，<strong>不应</strong>发送。</li></ul><h2 id="connect" tabindex="-1">CONNECT <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;CONNECT&quot;">​</a></h2><p>建立到目标 authority 的隧道，用于 HTTPS 经正向代理。</p><ul><li>目标必须是 <a href="/Front2Full/manual/computer-programming/http11/request-line">authority-form</a>：<code>CONNECT host:port HTTP/1.1</code>，主机端口均不可省。</li><li>代理返回 <code>2xx</code> 后，<strong>该连接上的后续字节不再按 HTTP 解析</strong>，纯双向转发。</li><li><code>2xx</code> 响应<strong>不得</strong>带 <code>Transfer-Encoding</code> 或 <code>Content-Length</code>（成帧规则第 2 条）。</li><li>失败时返回普通错误响应（<code>403</code>、<code>502</code>、<code>504</code>），连接不转隧道。</li><li>代理 <strong>SHOULD</strong> 限制可 CONNECT 的端口（通常仅 443），否则成为开放中继。</li></ul><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>查询目标资源或服务器整体的通信选项。</p><ul><li><code>OPTIONS *</code> 针对<strong>服务器整体</strong>（<a href="/Front2Full/manual/computer-programming/http11/request-line">asterisk-form</a>）；<code>OPTIONS /path</code> 针对该资源。</li><li>响应 <strong>SHOULD</strong> 带 <code>Allow</code>。</li><li>响应<strong>不可缓存</strong>（无 <code>Cache-Control</code> 时不应被存储）。</li><li>CORS 预检请求即 <code>OPTIONS</code> + <code>Access-Control-Request-*</code>，但那属于 Fetch 规范而非 HTTP 核心。</li></ul><h2 id="trace" tabindex="-1">TRACE <a class="header-anchor" href="#trace" aria-label="Permalink to &quot;TRACE&quot;">​</a></h2><p>回显收到的请求，用于诊断代理链。</p><ul><li>客户端 <strong>MUST NOT</strong> 在 <code>TRACE</code> 中发送请求体，<strong>MUST NOT</strong> 带敏感字段。</li><li>服务端响应体是<strong>收到的整个请求报文</strong>，<code>Content-Type: message/http</code>。</li><li>与 <code>Max-Forwards</code> 配合定位中间跳（见<a href="/Front2Full/manual/computer-programming/http11/proxy-fields">代理字段</a>）。</li><li><strong>安全</strong>：曾用于跨站追踪（XST）读取 <code>HttpOnly</code> Cookie，绝大多数生产服务器<strong>默认禁用</strong>（返回 <code>405</code>）。规范未要求禁用，但禁用是合理实践。</li></ul><h2 id="patch" tabindex="-1">PATCH <a class="header-anchor" href="#patch" aria-label="Permalink to &quot;PATCH&quot;">​</a></h2><p>RFC 5789 定义，不在 RFC 9110 核心方法内。对资源应用<strong>部分修改</strong>。</p><ul><li><strong>默认不幂等</strong>——请求体是「修改指令集」，重复应用可能叠加（如 <code>{&quot;op&quot;:&quot;add&quot;}</code>）。可通过 <code>If-Match</code> 变为条件性执行来获得幂等效果。</li><li>请求体是<strong>补丁文档</strong>，其格式由 <code>Content-Type</code> 指定：<code>application/json-patch+json</code>（RFC 6902）、<code>application/merge-patch+json</code>（RFC 7386）等。<strong>不是</strong>资源的部分表示。</li><li>服务端 <strong>MUST</strong> 原子应用：要么全部成功，要么全部不改。</li><li>不支持的补丁格式返回 <code>415 Unsupported Media Type</code>；补丁语法合法但无法应用返回 <code>422 Unprocessable Content</code>；<code>If-Match</code> 不匹配返回 <code>409</code>/<code>412</code>。</li><li>服务端可用 <code>Accept-Patch</code> 响应字段声明支持的补丁格式。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/status-codes">状态码总览与 1xx/2xx</a>。</p>',41)])])}const u=o(a,[["render",c]]);export{p as __pageData,u as default};
